	    public void EncodeBase64NVARCHARFields(CardPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.BankName)) //T4 find type == nText 
            {
                entityPM.BankName = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.BankName));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.BankAddress)) //T4 find type == nText 
            {
                entityPM.BankAddress = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.BankAddress));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.IBANNumber)) //T4 find type == nText 
            {
                entityPM.IBANNumber = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.IBANNumber));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SearchFields)) //T4 find type == nText 
            {
                entityPM.SearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.LocalName)) //T4 find type == nText 
            {
                entityPM.LocalName = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.LocalName));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.Notes)) //T4 find type == nText 
            {
                entityPM.Notes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.Notes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.CityName)) //T4 find type == nText 
            {
                entityPM.CityName = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.CityName));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.Address1)) //T4 find type == nText 
            {
                entityPM.Address1 = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.Address1));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.Address2)) //T4 find type == nText 
            {
                entityPM.Address2 = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.Address2));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SupportNotes)) //T4 find type == nText 
            {
                entityPM.SupportNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SupportNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SATCustomerName)) //T4 find type == nText 
            {
                entityPM.SATCustomerName = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SATCustomerName));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
